**Betik Dili: JavaScript (Örnek)**

```javascript
// Kullanıcı Onay Tercihleri Yönetimi

// Kullanıcı tercihlerini depolamak için bir nesne oluşturun
let userPreferences = {
  privacyPolicyAccepted: false,
  termsOfServiceAccepted: false,
  notificationsEnabled: true,
  emailNotifications: true,
  pushNotifications: false
};

// Fonksiyon: Kullanıcı tercihlerini kaydet
function saveUserPreferences(preferences) {
  // Tercihleri yerel depolama (Local Storage) veya bir sunucu tarafı veritabanında saklayın
  localStorage.setItem('userPreferences', JSON.stringify(preferences));
}

// Fonksiyon: Kullanıcının mevcut tercihlerini yükle
function loadUserPreferences() {
  const storedPreferences = localStorage.getItem('userPreferences');
  if (storedPreferences) {
    return JSON.parse(storedPreferences);
  }
  return { ...userPreferences }; // Varsayılan değerlerle başlat
}

// Fonksiyon: Onayları güncelle
function updatePreference(preference, value) {
  const currentPreferences = loadUserPreferences();
  currentPreferences[preference] = value;
  saveUserPreferences(currentPreferences);
}

// Örnek kullanım

// Kullanıcının gizlilik politikasını kabul ettirdiğinizde
updatePreference('privacyPolicyAccepted', true);

// Kullanıcı kullanım koşullarını kabul ettirdiğinizde
updatePreference('termsOfServiceAccepted', true);

// Bildirim tercihlerini güncelle
updatePreference('notificationsEnabled', false);
updatePreference('emailNotifications', false);
updatePreference('pushNotifications', true);

// Mevcut tercihleri görüntüle
const currentPrefs = loadUserPreferences();
console.log(currentPrefs);
```

